// UNHCR reports several displacement categories per country-year. We sum the
// forcibly-displaced categories into one figure per country and keep only the
// most recent year present, since the API can return two years at once.
const observedAt = new Date().toISOString().slice(0, 10);
const body = $input.first().json;

const rows = body?.items ?? body?.data;
if (!Array.isArray(rows)) {
  throw new Error('UNHCR returned an unexpected shape — no items array present.');
}

// refugees + asylum seekers + others of concern + internally displaced.
const FIELDS = ['refugees', 'asylum_seekers', 'idps', 'ooc', 'stateless'];

const latestYearByCountry = new Map();
for (const row of rows) {
  const iso3 = String(row?.coa_iso ?? row?.coa ?? '').toUpperCase();
  const year = Number(row?.year);
  if (iso3.length !== 3 || !Number.isFinite(year)) continue;
  const seen = latestYearByCountry.get(iso3);
  if (seen === undefined || year > seen) latestYearByCountry.set(iso3, year);
}

const totals = new Map();
for (const row of rows) {
  const iso3 = String(row?.coa_iso ?? row?.coa ?? '').toUpperCase();
  const year = Number(row?.year);
  if (iso3.length !== 3) continue;
  if (year !== latestYearByCountry.get(iso3)) continue;

  let sum = 0;
  for (const field of FIELDS) {
    const v = Number(row?.[field]);
    if (Number.isFinite(v) && v > 0) sum += v;
  }
  totals.set(iso3, (totals.get(iso3) ?? 0) + sum);
}

const observations = [...totals.entries()]
  // A zero total means "reported as zero", which is real data. A country absent
  // from the response is different, and is simply never emitted.
  .filter(([, value]) => Number.isFinite(value))
  .map(([iso3, value]) => ({
    iso3,
    source: 'unhcr',
    metric: 'displaced_persons',
    value,
    observedAt,
  }));

if (observations.length === 0) {
  throw new Error('UNHCR returned no usable country rows.');
}

return [{ json: { source: 'unhcr', observations, triggerScoring: false } }];
